import numpy as np
import math

def createReadableCalculations(raw_calculations):
    rows = raw_calculations.strip().split('\n')
    waist_sizes = np.arange(25, 55.1, 0.5)

    cols_per_row = 5
    for i in range(120, len(rows)):
        row = rows[i]
        columns = row.split()
        new_columns = []
        j = 1
        while j < len(columns):
            if columns[j] == "<" or columns[j] == ">":
                new_column = columns[j] + columns[j + 1]
                new_columns.append(new_column)
                j += 2
            else:
                new_columns.append(columns[j])
                j += 1
        print(f"{columns[0]}: {{")
        for j in range(int(len(new_columns) / cols_per_row)):
            print_str = "\t"
            for k in range(cols_per_row):
                index = j * cols_per_row + k
                print_str += f"{waist_sizes[index]}"
                print_str += ": "
                print_str += f"'{new_columns[index]}'"
                print_str += ", "
            print(print_str)
        last_row = "\t"
        last_row += f"55: '{new_columns[-1]}'"
        print(last_row)
        print("},")


